"use client"

import * as React from "react"
import { NavigationMenu as NavigationMenuPrimitive } from "@base-ui/react/navigation-menu"
import { cva } from "class-variance-authority"
import { cn } from "cn"

// NOTE: Update these paths if needed
import "../tokens.css"
import "./navigation-menu.css"

function NavigationMenu({
  align = "start",
  className,
  children,
  ...props
}: NavigationMenuPrimitive.Root.Props &
  Pick<NavigationMenuPrimitive.Positioner.Props, "align">) {
  return (
    <NavigationMenuPrimitive.Root
      data-slot="navigation-menu"
      className={cn("np-navigation-menu", className)}
      {...props}
    >
      {children}
      <NavigationMenuPositioner align={align} />
    </NavigationMenuPrimitive.Root>
  )
}

function NavigationMenuList({
  className,
  ...props
}: React.ComponentPropsWithRef<typeof NavigationMenuPrimitive.List>) {
  return (
    <NavigationMenuPrimitive.List
      data-slot="navigation-menu-list"
      className={cn("np-navigation-menu-list", className)}
      {...props}
    />
  )
}

function NavigationMenuItem({
  className,
  ...props
}: React.ComponentPropsWithRef<typeof NavigationMenuPrimitive.Item>) {
  return (
    <NavigationMenuPrimitive.Item
      data-slot="navigation-menu-item"
      className={cn("np-navigation-menu-item", className)}
      {...props}
    />
  )
}

const navigationMenuTriggerStyle = cva("np-navigation-menu-trigger")

function NavigationMenuTrigger({
  className,
  children,
  ...props
}: NavigationMenuPrimitive.Trigger.Props) {
  return (
    <NavigationMenuPrimitive.Trigger
      data-slot="navigation-menu-trigger"
      className={cn(navigationMenuTriggerStyle(), className)}
      {...props}
    >
      {children}
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width="24"
        height="24"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
        className="np-navigation-menu-trigger-icon"
        aria-hidden="true"
      >
        <path d="m6 9 6 6 6-6" />
      </svg>
    </NavigationMenuPrimitive.Trigger>
  )
}

function NavigationMenuContent({
  className,
  ...props
}: NavigationMenuPrimitive.Content.Props) {
  return (
    <NavigationMenuPrimitive.Content
      data-slot="navigation-menu-content"
      className={cn("np-navigation-menu-content", className)}
      {...props}
    />
  )
}

function NavigationMenuPositioner({
  className,
  side = "bottom",
  sideOffset = 8,
  align = "start",
  alignOffset = 0,
  ...props
}: NavigationMenuPrimitive.Positioner.Props) {
  return (
    <NavigationMenuPrimitive.Portal>
      <NavigationMenuPrimitive.Positioner
        data-slot="navigation-menu-positioner"
        side={side}
        sideOffset={sideOffset}
        align={align}
        alignOffset={alignOffset}
        className={cn("np-navigation-menu-positioner", className)}
        {...props}
      >
        <NavigationMenuPrimitive.Popup
          data-slot="navigation-menu-popup"
          className="np-navigation-menu-popup"
        >
          <NavigationMenuPrimitive.Viewport
            data-slot="navigation-menu-viewport"
            className="np-navigation-menu-viewport"
          />
        </NavigationMenuPrimitive.Popup>
      </NavigationMenuPrimitive.Positioner>
    </NavigationMenuPrimitive.Portal>
  )
}

function NavigationMenuLink({
  className,
  ...props
}: NavigationMenuPrimitive.Link.Props) {
  return (
    <NavigationMenuPrimitive.Link
      data-slot="navigation-menu-link"
      className={cn("np-navigation-menu-link", className)}
      {...props}
    />
  )
}

export {
  NavigationMenu,
  NavigationMenuContent,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
  NavigationMenuPositioner,
  NavigationMenuTrigger,
  navigationMenuTriggerStyle,
}

/* nepui — Navigation Menu */

:is(.np-navigation-menu, [data-np-navigation-menu]) {
  --np-navigation-menu-gap: calc(var(--np-spacing) * 2);
  --np-navigation-menu-offset: 0.5rem;
  --np-navigation-menu-duration: 350ms;
  --np-navigation-menu-easing: cubic-bezier(0.22, 1, 0.36, 1);
  --np-navigation-menu-bg: var(--np-popover);
  --np-navigation-menu-color: var(
    --np-popover-foreground,
    var(--np-foreground)
  );
  --np-navigation-menu-shadow:
    0 0 0 1px color-mix(in oklab, var(--np-foreground) 10%, transparent),
    var(--np-shadow-md);

  position: relative;
  display: flex;
  flex: 1;
  align-items: center;
  justify-content: center;
  max-width: max-content;
}

:is(.np-navigation-menu-list, [data-np-navigation-menu-list]) {
  display: flex;
  flex: 1;
  align-items: center;
  justify-content: center;
  gap: var(--np-navigation-menu-gap);
  margin: 0;
  padding: 0;
  list-style: none;
}

:is(.np-navigation-menu-item, [data-np-navigation-menu-item]) {
  position: relative;
}

:is(.np-navigation-menu-trigger, [data-np-navigation-menu-trigger]) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  width: max-content;
  height: 2rem;
  margin: 0;
  padding: 0.375rem 0.625rem;
  border: 0;
  border-radius: var(--np-radius-lg);
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1.25rem;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  outline: none;
  transition: background-color 150ms;
}

:is(.np-navigation-menu-trigger, [data-np-navigation-menu-trigger]):is(
  :hover,
  :focus
) {
  background: var(--np-muted);
}

:is(.np-navigation-menu-trigger, [data-np-navigation-menu-trigger]):is(
  [data-popup-open],
  [aria-expanded="true"],
  [data-active]
) {
  background: color-mix(in oklab, var(--np-muted) 50%, transparent);
}

:is(.np-navigation-menu-trigger, [data-np-navigation-menu-trigger]):is(
    [data-popup-open],
    [aria-expanded="true"]
  ):is(:hover, :focus) {
  background: var(--np-muted);
}

:is(
  .np-navigation-menu-trigger,
  [data-np-navigation-menu-trigger]
):focus-visible {
  outline: 2px solid var(--np-ring);
  outline-offset: -2px;
}

:is(.np-navigation-menu-trigger, [data-np-navigation-menu-trigger]):disabled {
  opacity: 0.5;
  pointer-events: none;
}

:is(.np-navigation-menu-trigger-icon, [data-np-navigation-menu-trigger-icon]) {
  position: relative;
  inset-block-start: 1px;
  flex: none;
  width: 0.75rem;
  height: 0.75rem;
  margin-inline-start: calc(var(--np-spacing) * 1);
  transition: transform 300ms;
}

:is(.np-navigation-menu-trigger, [data-np-navigation-menu-trigger]):is(
    [data-popup-open],
    [aria-expanded="true"]
  )
  :is(
    .np-navigation-menu-trigger-icon,
    [data-np-navigation-menu-trigger-icon]
  ) {
  transform: rotate(180deg);
}

:is(.np-navigation-menu-link, [data-np-navigation-menu-link]) {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem;
  border-radius: var(--np-radius-md);
  color: inherit;
  font-size: 0.875rem;
  line-height: 1.25rem;
  text-decoration: none;
  outline: none;
  transition: background-color 150ms;
}

:is(.np-navigation-menu-link, [data-np-navigation-menu-link]):is(
  :hover,
  :focus
) {
  background: var(--np-muted);
}

:is(.np-navigation-menu-link, [data-np-navigation-menu-link]):is(
  [data-active],
  [aria-current="page"]
) {
  background: color-mix(in oklab, var(--np-muted) 50%, transparent);
}

:is(.np-navigation-menu-link, [data-np-navigation-menu-link]):is(
    [data-active],
    [aria-current="page"]
  ):is(:hover, :focus) {
  background: var(--np-muted);
}

:is(.np-navigation-menu-link, [data-np-navigation-menu-link]):focus-visible {
  outline: 2px solid var(--np-ring);
  outline-offset: -2px;
}

:is(.np-navigation-menu-link, [data-np-navigation-menu-link]) > svg {
  flex: none;
  width: 1rem;
  height: 1rem;
}

:is(.np-navigation-menu-link-text, [data-np-navigation-menu-link-text]) {
  display: flex;
  flex-direction: column;
  gap: calc(var(--np-spacing) * 1);
}

:is(.np-navigation-menu-link-title, [data-np-navigation-menu-link-title]) {
  font-weight: 500;
  line-height: 1;
}

:is(
  .np-navigation-menu-link-description,
  [data-np-navigation-menu-link-description]
) {
  display: -webkit-box;
  overflow: hidden;
  color: var(--np-muted-foreground);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
}

:is(.np-navigation-menu-content, [data-np-navigation-menu-content]) {
  box-sizing: border-box;
  width: auto;
  height: 100%;
  padding: calc(var(--np-spacing) * 1);
  border: 1px solid var(--np-border);
  border-radius: var(--np-radius-lg);
  box-shadow: var(--np-shadow-md);
  background-color: var(--np-popover);
}

:is(.np-navigation-menu-positioner, [data-np-navigation-menu-positioner]) {
  z-index: 50;
  isolation: isolate;
  width: var(--positioner-width);
  height: var(--positioner-height);
  max-width: var(--available-width);
  background-color: var(--navigation-menu-bg);
  transition-property: top, left, right, bottom;
  transition-duration: var(--np-navigation-menu-duration);
  transition-timing-function: var(--np-navigation-menu-easing);
}

:is(
  .np-navigation-menu-positioner,
  [data-np-navigation-menu-positioner]
)[data-instant] {
  transition: none;
}

:is(.np-navigation-menu-popup, [data-np-navigation-menu-popup]) {
  position: relative;
  width: var(--popup-width);
  height: var(--popup-height);
  border-radius: var(--np-radius-lg);
  background: var(--np-navigation-menu-bg);
  color: var(--np-navigation-menu-color);
  box-shadow: var(--np-navigation-menu-shadow);
  outline: none;
  transform-origin: var(--transform-origin);
  transition-property: opacity, transform, width, height, scale, translate;
  transition-duration: var(--np-navigation-menu-duration);
  transition-timing-function: var(--np-navigation-menu-easing);
}

:is(.np-navigation-menu-popup, [data-np-navigation-menu-popup]):is(
  [data-starting-style],
  [data-ending-style]
) {
  opacity: 0;
  scale: 0.9;
}

:is(
  .np-navigation-menu-popup,
  [data-np-navigation-menu-popup]
)[data-ending-style] {
  transition-duration: 150ms;
}

:is(.np-navigation-menu-viewport, [data-np-navigation-menu-viewport]) {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

:is(.np-navigation-menu-popup, [data-np-navigation-menu-popup])
  :is(.np-navigation-menu-content, [data-np-navigation-menu-content]) {
  transition-property: opacity, transform, translate;
  transition-duration: var(--np-navigation-menu-duration);
  transition-timing-function: var(--np-navigation-menu-easing);
}

:is(.np-navigation-menu-content, [data-np-navigation-menu-content]):is(
  [data-starting-style],
  [data-ending-style]
) {
  opacity: 0;
}

:is(
    .np-navigation-menu-content,
    [data-np-navigation-menu-content]
  )[data-starting-style][data-activation-direction="left"] {
  translate: -50% 0;
}

:is(
    .np-navigation-menu-content,
    [data-np-navigation-menu-content]
  )[data-starting-style][data-activation-direction="right"] {
  translate: 50% 0;
}

:is(
    .np-navigation-menu-content,
    [data-np-navigation-menu-content]
  )[data-ending-style][data-activation-direction="left"] {
  translate: 50% 0;
}

:is(
    .np-navigation-menu-content,
    [data-np-navigation-menu-content]
  )[data-ending-style][data-activation-direction="right"] {
  translate: -50% 0;
}

:is(.np-navigation-menu-item, [data-np-navigation-menu-item])
  > :is(.np-navigation-menu-content, [data-np-navigation-menu-content]) {
  position: absolute;
  inset-block-start: calc(100% + var(--np-navigation-menu-offset));
  inset-inline-start: 0;
  z-index: 50;
  display: none;
  min-width: max-content;
  height: auto;
  border-radius: var(--np-radius-lg);
  background: var(--np-navigation-menu-bg);
  color: var(--np-navigation-menu-color);
  box-shadow: var(--np-navigation-menu-shadow);
  opacity: 0;
  translate: 0 -calc(var(--np-spacing) * 1);
  scale: 0.95;
  transform-origin: top;
  transition-property: opacity, translate, scale, display;
  transition-duration: 200ms;
  transition-timing-function: var(--np-navigation-menu-easing);
  transition-behavior: allow-discrete;
}

:is(.np-navigation-menu-item, [data-np-navigation-menu-item])
  > :is(
    .np-navigation-menu-content,
    [data-np-navigation-menu-content]
  )::before {
  content: "";
  position: absolute;
  inset-block: calc(var(--np-navigation-menu-offset) * -1) auto;
  inset-inline: 0;
  height: var(--np-navigation-menu-offset);
}

:is(.np-navigation-menu-item, [data-np-navigation-menu-item])[data-open]
  > :is(.np-navigation-menu-content, [data-np-navigation-menu-content]) {
  display: block;
  opacity: 1;
  translate: 0 0;
  scale: 1;
}

@starting-style {
  :is(.np-navigation-menu-item, [data-np-navigation-menu-item])[data-open]
    > :is(.np-navigation-menu-content, [data-np-navigation-menu-content]) {
    opacity: 0;
    translate: 0 -calc(var(--np-spacing) * 1);
    scale: 0.95;
  }
}

@media (prefers-reduced-motion: reduce) {
  :is(.np-navigation-menu-positioner, [data-np-navigation-menu-positioner]),
  :is(.np-navigation-menu-popup, [data-np-navigation-menu-popup]),
  :is(.np-navigation-menu-content, [data-np-navigation-menu-content]),
  :is(
    .np-navigation-menu-trigger-icon,
    [data-np-navigation-menu-trigger-icon]
  ) {
    transition: none;
  }
}
